-- LIBRARY_STAGING.DBT_CROGERS.STG_FED_FJC_IDB__FEDERAL_COURT_CASES
create or replace view LIBRARY_STAGING.DBT_CROGERS.STG_FED_FJC_IDB__FEDERAL_COURT_CASES(
	CIRCUIT,
	DISTRICT,
	OFFICE,
	DOCKET,
	JUDGE,
	CASE_ID,
	FILE_DATE,
	TERM_DATE,
	ORIGIN_CODE,
	JUDGMENT_CODE,
	NATURE_OF_SUIT_CODE,
	JURISDICTION_CODE,
	PROSE_CODE,
	GENDER_CODE,
	CRIMINAL_COUNT,
	STAT_YEAR,
	TAPE_YEAR,
	DISPOSITION_CODE,
	AMOUNT_RECEIVED,
	SECTION_CODE,
	SUBSECTION_CODE,
	_INGESTED_AT,
	_SOURCE_RUN_ID
) as (
    

with

source as (

    select * from LIBRARY_RAW.LANDING.FED_FJC_IDB

),

renamed_cast as (

    select

        -- identifiers
        circuit                                         as circuit,
        district                                        as district,
        office                                          as office,
        docket                                          as docket,
        judge                                           as judge,

        -- derived case_id (surrogate on stable business fields)
        md5(cast(coalesce(cast(circuit as TEXT), '_dbt_utils_surrogate_key_null_') || '-' || coalesce(cast(district as TEXT), '_dbt_utils_surrogate_key_null_') || '-' || coalesce(cast(office as TEXT), '_dbt_utils_surrogate_key_null_') || '-' || coalesce(cast(docket as TEXT), '_dbt_utils_surrogate_key_null_') as TEXT))
                                                        as case_id,

        -- dates
        try_to_date(filedate, 'YYYYMMDD')               as file_date,
        try_to_date(termdate, 'YYYYMMDD')               as term_date,

        -- numeric fields
        try_to_number(origin)                           as origin_code,
        try_to_number(judgment)                         as judgment_code,
        try_to_number(nos)                              as nature_of_suit_code,
        try_to_number(juris)                            as jurisdiction_code,
        try_to_number(prose)                            as prose_code,
        try_to_number(gender)                           as gender_code,
        try_to_number(criminal_count)                   as criminal_count,
        try_to_number(stat_year)                        as stat_year,
        try_to_number(tapeyear)                         as tape_year,
        try_to_number(disp)                             as disposition_code,
        try_to_double(amtrec)                           as amount_received,
        try_to_number(section)                          as section_code,
        try_to_number(subsection)                       as subsection_code,

        -- metadata
        _ingested_at,
        _source_run_id

    from source

),

deduped as (

    select *
    from renamed_cast
    qualify row_number() over (
        partition by case_id
        order by _ingested_at desc
    ) = 1

)

select * from deduped
  );

